	12230100: {
		names: [{ nominative: "Άγιος Ναούμ ο Θεοφόρος και θαυματουργός", short: "Άγιος Ναούμ" }],
		biographies: [
			{
				id: "saintgr",
				copyright: "saint.gr",
				text: "Ο Άγιος Ναούμ υπήρξε συνεργάτης του Κυρίλλου και Μεθοδίου, τον 9ο αιώνα (842 μ.Χ.), στους αγώνες τους για τη διάδοση της χριστιανικής πίστης στη Βουλγαρία. Και στο βαρύ αυτό έργο, όπου συνάντησαν μεγάλα εμπόδια και επικίνδυνες αντιστάσεις, η παρουσία του Ναούμ είχε μεγάλη επίδραση. Διότι στη δύναμη της διδασκαλίας του, πρόσθετε και την εντύπωση, που προκαλούσαν τα θαύματα που ενεργούσε με τη χάρη του Θεού.<br/><br/>Ο Ναούμ, επιστρέφοντας από τη Ρώμη, όπου πήγε στον τότε Πάπα Αδριανό, πέρασε και από τη Γερμανία, όπου υπήρχαν πολλές και διάφορες αιρέσεις. Και αφού κήρυξε και εκεί αγωνιζόμενος για την Ορθοδοξία, επανήλθε και πάλι στη Βουλγαρία. Εκεί, οργάνωσε μαζί με άλλους συναγωνιστές του, σώμα εσωτερικής ιεραποστολής και εργάστηκε θερμότατα για τη διάδοση του χριστιανισμού με τα κηρύγματά του και τις συνεχείς διδακτικές περιοδείες του.<br/><br/>Ο θάνατος τον βρήκε όρθιο, να κοπιάζει μέχρι τελευταίας του πνοής για τον ευσεβή σκοπό του.",
			},
		],
		info: [],
		refs: [],
		services: [],
		hymns: [],
	},
